-- 000573 — set OPU (oil per unit) to 0 for 2,550 products that finance
-- confirmed have NO oil cost (key = legacy sys id cost_product_master.cpm_flex_02).
--
-- Effect: F_YARN_OIL_COST multiplies by OPU in both the PTY/POY and SUPERBA
-- branches, so OIL_COST becomes 0; the PTY oil gain is also 0, POY oil gain
-- stays OIL_GAIN_POY_DEFAULT. Prod pre-check: 2,550/2,550 match, OPU already 0
-- for nearly all; 5 non-zero (2 PTY, 3 ACY), 1 PTY with NULL value, 3 products
-- (TCY/ITY/ATY) without an OPU CAPP row.
--
-- Scope: only products that HAVE an OPU applicable-param (CAPP) row (they use
-- OPU). No CAPP rows are added. Runs after 000572, which may add OPU CAPP rows
-- to former TCY/ATY melange products; those are covered too.
--
-- Reversible: cost_product_parameter_opu_backup_573 stores had_row/old_value.
-- Idempotent: backup rows are inserted only if not yet backed up; the upsert
-- changes only rows whose value is distinct from 0.

BEGIN;

SET LOCAL lock_timeout = '10s';

CREATE TABLE IF NOT EXISTS cost_product_parameter_opu_backup_573 (
    cpp_product_sys_id BIGINT      PRIMARY KEY,
    had_row            BOOLEAN     NOT NULL,
    old_value          NUMERIC,
    backed_up_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
COMMENT ON TABLE cost_product_parameter_opu_backup_573 IS
    'Backup written by migration 000573 (OPU = 0 for no-oil products): previous OPU value per product; read by its down migration. Safe to drop once 000573 is final.';

CREATE TEMP TABLE tmp_no_oil_573 (legacy_id VARCHAR(20) PRIMARY KEY) ON COMMIT DROP;

-- Targets: list products that have an OPU CAPP row.
CREATE TEMP TABLE tmp_targets_573 ON COMMIT DROP AS
SELECT pm.cpm_product_sys_id AS product_id, mp.id AS param_id
FROM cost_product_master pm
JOIN tmp_no_oil_573 k ON k.legacy_id = pm.cpm_flex_02
JOIN mst_parameter mp ON mp.param_code = 'OPU' AND mp.deleted_at IS NULL
JOIN cost_product_applicable_param c
     ON c.capp_product_sys_id = pm.cpm_product_sys_id AND c.capp_param_id = mp.id;

SELECT t.product_id, p.cpp_product_sys_id IS NOT NULL, p.cpp_value_numeric
FROM tmp_targets_573 t
LEFT JOIN cost_product_parameter p
       ON p.cpp_product_sys_id = t.product_id AND p.cpp_param_id = t.param_id
ON CONFLICT (cpp_product_sys_id) DO NOTHING;

CREATE TEMP TABLE tmp_updated_573 ON COMMIT DROP AS
WITH upd AS (
    UPDATE cost_product_parameter p
    SET cpp_value_numeric = 0,
        cpp_filled_by     = 'migration_000573'
    FROM tmp_targets_573 t
    WHERE p.cpp_product_sys_id = t.product_id
      AND p.cpp_param_id = t.param_id
      AND p.cpp_value_numeric IS DISTINCT FROM 0
    RETURNING p.cpp_product_sys_id
)
SELECT * FROM upd;

CREATE TEMP TABLE tmp_inserted_573 ON COMMIT DROP AS
WITH ins AS (
        cpp_product_sys_id, cpp_param_id, cpp_value_numeric,
        cpp_filled_by, cpp_created_by
    )
    SELECT t.product_id, t.param_id, 0, 'migration_000573', 'migration_000573'
    FROM tmp_targets_573 t
    ON CONFLICT ON CONSTRAINT cpp_unique_product_param DO NOTHING
    RETURNING cpp_product_sys_id
)
SELECT * FROM ins;

DO $$
DECLARE
    v_matched INT;
    v_targets INT;
    v_upd     INT;
    v_ins     INT;
BEGIN
    SELECT COUNT(*) INTO v_matched
    FROM cost_product_master pm JOIN tmp_no_oil_573 k ON k.legacy_id = pm.cpm_flex_02;
    SELECT COUNT(*) INTO v_targets FROM tmp_targets_573;
    SELECT COUNT(*) INTO v_upd FROM tmp_updated_573;
    SELECT COUNT(*) INTO v_ins FROM tmp_inserted_573;
    RAISE NOTICE '000573: list products matched = %, updated to OPU 0 = %, inserted = %, skipped (no OPU CAPP) = %',
        v_matched, v_upd, v_ins, v_matched - v_targets;
END $$;

COMMIT;
